{"odds.py": "'''Implied probability for American odds (standard library only).'''

import math

__all__ = ['american_probability']


def _coerce(value):
    '''Return a finite int/float for supported inputs, else raise ValueError.'''
    if isinstance(value, bool):
        raise ValueError('bool is not a valid odds value')
    if isinstance(value, str):
        text = value.strip()
        try:
            number = float(text)
        except (TypeError, ValueError):
            raise ValueError('not a numeric string') from None
        if not math.isfinite(number):
            raise ValueError('odds must be finite')
        return number
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError('odds must be finite')
        return value
    raise ValueError('unsupported odds type: %s' % type(value).__name__)


def american_probability(value):
    '''Return the implied probability of American odds.

    Positive odds use 100 / (value + 100); negative odds use
    -value / (-value + 100).  Accepts int, float and numeric strings
    (surrounding whitespace allowed); the value must be finite with an
    absolute value of at least 100.  Anything else raises ValueError.
    The result is never rounded.
    '''
    number = _coerce(value)
    if abs(number) < 100:
        raise ValueError('odds magnitude must be at least 100')
    if number > 0:
        try:
            return 100 / (number + 100)
        except OverflowError:
            return 0.0
    try:
        return -number / (-number + 100)
    except OverflowError:
        return 1.0
", "selection.py": "'''Latest eligible observation (standard library only).'''

from datetime import datetime, timezone

from odds import american_probability

__all__ = ['select_latest']


def _instant(value):
    '''Parse an ISO-8601 timestamp into an aware UTC datetime, else None.'''
    if not isinstance(value, str):
        return None
    text = value
    if text.endswith('Z'):
        text = text[:-1] + '+00:00'
    try:
        parsed = datetime.fromisoformat(text)
    except (ValueError, TypeError):
        return None
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        return None
    return parsed.astimezone(timezone.utc)


def _asof_instant(asof):
    '''Validate asof and return it as an aware UTC datetime.'''
    if not isinstance(asof, datetime):
        raise ValueError('asof must be a datetime')
    if asof.tzinfo is None or asof.utcoffset() is None:
        raise ValueError('asof must be timezone-aware')
    return asof.astimezone(timezone.utc)


def select_latest(rows, asof):
    '''Return the original eligible row with the newest observed_at.

    A row qualifies only when it is a dict with a non-empty string id,
    valid American odds and timezone-aware ISO observed_at / expires_at
    timestamps with observed_at <= asof < expires_at and
    observed_at < expires_at, compared as absolute instants.  Ties on
    observed_at are broken by the lexicographically smallest id.
    Returns None when no row qualifies.  Inputs are never mutated.
    '''
    asof_utc = _asof_instant(asof)
    if rows is None:
        return None
    best = None
    best_observed = None
    best_id = None
    for row in rows:
        if not isinstance(row, dict):
            continue
        row_id = row.get('id')
        if not isinstance(row_id, str) or row_id == '':
            continue
        try:
            american_probability(row.get('odds'))
        except (ValueError, TypeError):
            continue
        observed = _instant(row.get('observed_at'))
        if observed is None:
            continue
        expires = _instant(row.get('expires_at'))
        if expires is None:
            continue
        if not (observed <= asof_utc < expires):
            continue
        if not (observed < expires):
            continue
        if (best is None or observed > best_observed
                or (observed == best_observed and row_id < best_id)):
            best = row
            best_observed = observed
            best_id = row_id
    return best
