'''Implied probability for American odds (standard library only).'''

import math

__all__ = ['american_probability']


def _coerce(value):
    '''Return a finite int/float for supported inputs, else raise ValueError.'''
    if isinstance(value, bool):
        raise ValueError('bool is not a valid odds value')
    if isinstance(value, str):
        text = value.strip()
        try:
            number = float(text)
        except (TypeError, ValueError):
            raise ValueError('not a numeric string: %r' % (value,)) from None
        if not math.isfinite(number):
            raise ValueError('odds must be finite: %r' % (value,))
        return number
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError('odds must be finite: %r' % (value,))
        return value
    raise ValueError('unsupported odds type: %s' % type(value).__name__)


def american_probability(value):
    '''Return the implied probability of American odds.

    Positive odds use 100 / (value + 100); negative odds use
    -value / (-value + 100).  Accepts int, float and numeric strings
    (surrounding whitespace allowed); the value must be finite with an
    absolute value of at least 100.  Anything else raises ValueError.
    The result is never rounded.
    '''
    number = _coerce(value)
    if abs(number) < 100:
        raise ValueError('odds magnitude must be at least 100: %r' % (value,))
    if number > 0:
        try:
            return 100 / (number + 100)
        except OverflowError:
            return 0.0
    try:
        return -number / (-number + 100)
    except OverflowError:
        return 1.0
