"""American odds implied probability conversion."""

import math

__all__ = ["american_probability"]


def _to_number(value):
    """Convert supported input into a numeric value.

    Accepts int, float and numeric strings (surrounding whitespace allowed).
    Raises ValueError for anything else or for non-finite values.
    """
    if isinstance(value, bool):
        raise ValueError("bool is not a valid odds value: {!r}".format(value))
    if isinstance(value, str):
        text = value.strip()
        try:
            number = float(text)
        except (TypeError, ValueError):
            raise ValueError("not a numeric string: {!r}".format(value))
        if not math.isfinite(number):
            raise ValueError("odds must be finite: {!r}".format(value))
        return number
    if isinstance(value, int):
        # Every int is finite; keep exact integer arithmetic.
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("odds must be finite: {!r}".format(value))
        return value
    raise ValueError("unsupported odds type: {}".format(type(value).__name__))
```

