def _coerce(value):
    """Return a finite int/float for supported inputs, else raise ValueError."""
    if isinstance(value, bool):
        raise ValueError("bool is not a valid odds value")
    if isinstance(value, str):
        text = value.strip()
        try:
            number = float(text)
        except (TypeError, ValueError):
            raise ValueError("not a numeric string: %r" % (value,))
        if not math.isfinite(number):
            raise ValueError("odds must be a finite value: %r" % (value,))
        return number
    if isinstance(value, int):
